93	/****************************************************************************
94	 * 内部：LVGL 轮询 timer（1s）
95	 ****************************************************************************/
96	static void dm_als_timer_cb(lv_timer_t *timer)
97	{
98	    (void)timer;
99	    struct sensor_light light;
100	    struct pollfd fds;
101	    int ret;
102	
103	    if (s_light_fd < 0)
104	        return;
105	
106	    fds.fd = s_light_fd;
107	    fds.events = POLLIN;
108	    fds.revents = 0;
109	
110	    ret = poll(&fds, 1, 0);
111	    if (ret <= 0)
112	        return;   /* 无新数据：正常（驱动按自己的节奏推送） */
113	
114	    if (orb_copy(ORB_ID(sensor_light), s_light_fd, &light) == OK) {
115	        int lux = (int)light.light;
116	        if (lux < 0)
117	            lux = 0;
118	        s_cur_lux = lux;
119	        dm_als_dark_tick(lux, lv_tick_get());
120	    }
121	}
122	
123	/****************************************************************************
124	 * 公开接口
125	 ****************************************************************************/
126	int dm_als_init(void)
127	{
128	    if (s_light_fd >= 0)
129	        return 0;   /* 已初始化 */
130	
131	    s_light_fd = orb_subscribe_multi(ORB_ID(sensor_light), 0);
132	    if (s_light_fd < 0) {
133	        /* 无 LTR553 ALS：不打扰（锁屏亮度行显示 "--"） */
134	        return -1;
135	    }
136	
137	    s_poll_timer = lv_timer_create(dm_als_timer_cb, DM_ALS_POLL_MS, NULL);
138	    if (!s_poll_timer) {
139	        /* timer 创建失败：释放订阅 fd，避免 fd 泄漏 + 亮度永远 "--" */
140	        orb_unsubscribe(s_light_fd);
141	        s_light_fd = -1;
142	        return -1;
143	    }
144	    lv_timer_set_repeat_count(s_poll_timer, -1);   /* 无限循环 */
145	    s_start_ms = lv_tick_get();   /* P156：开机稳定期基准（init 时刻） */
146	
147	    return 0;
148	}
