51	    /* P157：确认门——必须见过真实亮度（lux ≥ 确认阈值）后，低亮度读数
52	     * 才可信。若传感器从头到尾只报 0（坏数据/未就绪/遮光），无法确认
53	     * "真暗"，永不弹窗（用户：要有确切低亮度才弹，不要一开始就弹） */
54	    if (lux >= DM_ALS_CONFIRM_LUX)
55	        s_seen_bright = true;
56	    if (!s_seen_bright)
57	        return;
58	
59	    /* P156：开机稳定期内不触发暗光弹窗——驱动首个有效 ALS 转换前
60	     * 可能持续推 0（CH0 未就绪），开机即弹"知道了"是误报 */
61	    if (now_ms - s_start_ms < DM_ALS_STARTUP_MS)
62	        return;
63	
64	    bool dark_now = (lux >= 0) && (lux < DM_ALS_DARK_LUX);
65	
66	    if (dark_now) {
67	        if (!s_dark_active) {
68	            /* 刚进入暗光：记录候选起点，等 debounce 确认 */
69	            if (s_debounce_start == 0)
70	                s_debounce_start = now_ms;
71	            if (now_ms - s_debounce_start >= DM_ALS_DARK_DEBOUNCE_MS) {
72	                /* 防抖通过：确认暗光 */
73	                s_dark_active = true;
74	                s_debounce_start = 0;
75	                /* 冷却检查：距上次触发 ≥ 冷却期才再次提醒 */
76	                if (s_last_trigger == 0 ||
77	                    now_ms - s_last_trigger >= DM_ALS_DARK_COOLDOWN_MS) {
78	                    s_last_trigger = now_ms;
79	                    if (s_dark_cb)
