81	                }
82	            }
83	        }
84	        /* 已确认暗光：保持，不重复触发（冷却已含） */
85	    }
86	    else {
87	        /* 光线恢复：重置状态机 */
88	        s_dark_active = false;
89	        s_debounce_start = 0;
